export interface LeadCapture {
  leadCaptureId: number;
  companyId?: number; // Nullable per DB spec
  fullName: string;
  email: string;
  companyName?: string;
  phone?: string;
  jobTitle?: string;
  message?: string;
  leadSource: string;
  interestArea?: string;
  status: 'new' | 'contacted' | 'qualified' | 'converted' | 'disqualified';
  assignedTo?: number; // FK to employees
  privacyConsentAccepted: boolean;
  created_At: string;
  updated_at?: string;
}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

// For create, companyId is explicitly stripped by backend, so omit it from payload type.
// Also omit auto-generated fields and fields defaulted by backend.
export interface CreateLeadCaptureRequest extends Omit<LeadCapture, "leadCaptureId" | "companyId" | "status" | "assignedTo" | "created_At" | "updated_at"> {}

export interface UpdateLeadCaptureRequest extends Partial<Omit<LeadCapture, "leadCaptureId" | "created_At">> {}

// GET ALL — POST /all_leadCaptures
export async function getAllLeadCaptures(companyId: number, searchTerm?: string, filterStatus?: string, filterInterestArea?: string, offset: number = 0, limit: number = 20): Promise<LeadCapture[]> {
  const payload: any = { companyId, offset, limit };
  if (searchTerm) payload.searchTerm = searchTerm;
  if (filterStatus) payload.status = filterStatus;
  if (filterInterestArea) payload.interestArea = filterInterestArea;

  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ leadCaptures: [payload] }), // Backend expects plural key wrapping
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? []; // unwrap: SP wraps array under plural key
}

// GET ONE — POST /one_leadCaptures
export async function getLeadCaptureById(id: number, companyId: number): Promise<LeadCapture | null> {
  const res = await fetch(BASE_URL + "/one_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ leadCaptures: [{ leadCaptureId: id, companyId: companyId }] }), // Backend expects plural key wrapping
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures?.[0] ?? null;
}

// CREATE — action: 1
export async function createLeadCapture(payload: CreateLeadCaptureRequest): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ leadCaptures: [{ "action": 1, ...payload }] }),
  });
  // Per ADR-002 and backend implementation, backend returns 400 for errors (including duplicates)
  if (!res.ok) {
    const errorBody = await res.json(); // Attempt to parse for specific error messages
    const errorMessage = errorBody?.error?.message || errorBody?.message || JSON.stringify(errorBody);
    throw new Error(errorMessage ?? 'Error desconocido');
  }
  return await res.json();
}

// UPDATE — action: 2
export async function updateLeadCapture(id: number, companyId: number, payload: UpdateLeadCaptureRequest): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ leadCaptures: [{ "action": 2, "leadCaptureId": id, "companyId": companyId, ...payload }] }),
  });
  if (!res.ok) {
    const errorBody = await res.json();
    const errorMessage = errorBody?.error?.message || errorBody?.message || JSON.stringify(errorBody);
    throw new Error(errorMessage ?? 'Error desconocido');
  }
  return await res.json();
}

// DELETE — action: 3
export async function deleteLeadCapture(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ leadCaptures: [{ "action": 3, "leadCaptureId": id, "companyId": companyId }] }),
