const PAGE_SIZE = 20;

// Helper to convert UTC dates to Hermosillo (UTC-7)
const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Subtract 7 hours (7 * 60 * 60 * 1000 milliseconds)
  const hermosilloDate = new Date(d.getTime() - 7 * 60 * 60 * 1000);
  return hermosilloDate.toLocaleString('es-MX', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
};

const LeadCapturePage: React.FC = () => {
  const { companyId } = useUser();
  const history = useHistory();

  const [leads, setLeads] = useState<LeadCapture[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
  const [filterInterestArea, setFilterInterestArea] = useState<string | undefined>(undefined);

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newLeadData, setNewLeadData] = useState<CreateLeadCaptureRequest>({
    fullName: '',
    email: '',
    privacyConsentAccepted: false,
    leadSource: '',
  });
  const [createFormErrors, setCreateFormErrors] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);

  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const infiniteScrollRef = useRef<HTMLIonInfiniteScrollElement>(null);

  const [popoverState, setPopoverState] = useState({
    showAlertPopover: false,
    showMailPopover: false,
    event: undefined as any,
  });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const validateCreateForm = () => {
    const errors: Record<string, string> = {};
    if (!newLeadData.fullName.trim()) errors.fullName = 'El nombre completo es requerido.';
    if (!newLeadData.email.trim()) {
      errors.email = 'El correo electrónico es requerido.';
    } else if (!/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(newLeadData.email)) {
      errors.email = 'Formato de correo electrónico inválido.';
    }
    if (!newLeadData.leadSource.trim()) errors.leadSource = 'La fuente del lead es requerida.';
    if (!newLeadData.privacyConsentAccepted) errors.privacyConsentAccepted = 'Debe aceptar la política de privacidad.';
    setCreateFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const loadLeads = async (initialLoad: boolean = false, pageNum: number = page) => {
    if (loading) return;
    setLoading(true);
    setError('');

    try {
      const offset = initialLoad ? 0 : pageNum * PAGE_SIZE;
      const fetchedLeads = await getAllLeadCaptures(
        companyId,
        searchTerm,
        filterStatus,
        filterInterestArea,
        offset,
        PAGE_SIZE
      );

      if (initialLoad) {
        setLeads(fetchedLeads);
      } else {
        setLeads((prev) => [...prev, ...fetchedLeads]);
      }

      setPage(pageNum + 1);
      setHasMore(fetchedLeads.length === PAGE_SIZE);
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar leads');
      setHasMore(false);
    } finally {
      setLoading(false);
      if (infiniteScrollRef.current) {
        infiniteScrollRef.current.complete();
      }
    }
