                labelPlacement="floating"
                type="tel"
                value={newLeadData.phone}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setNewLeadData(p => ({ ...p, phone: e.detail.value! }))}
              />
            </div>
            <div className="wizard-field-group">
              <IonInput
                fill="outline"
                label="Título del Puesto"
                labelPlacement="floating"
                value={newLeadData.jobTitle}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setNewLeadData(p => ({ ...p, jobTitle: e.detail.value! }))}
              />
            </div>
            <div className="wizard-field-group">
              <IonInput
                fill="outline"
                label="Fuente del Lead *"
                labelPlacement="floating"
                value={newLeadData.leadSource}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setNewLeadData(p => ({ ...p, leadSource: e.detail.value! }))}
                className={createFormErrors.leadSource ? 'ion-invalid ion-touched' : ''}
                errorText={createFormErrors.leadSource}
              />
            </div>
            <div className="wizard-field-group">
              <IonInput
                fill="outline"
                label="Área de Interés"
                labelPlacement="floating"
                value={newLeadData.interestArea}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setNewLeadData(p => ({ ...p, interestArea: e.detail.value! }))}
              />
            </div>
            <div className="wizard-field-group">
              <IonTextarea
                fill="outline"
                label="Mensaje"
                labelPlacement="floating"
                value={newLeadData.message}
                onIonInput={(e: CustomEvent<HTMLIonTextareaElement>) => setNewLeadData(p => ({ ...p, message: e.detail.value! }))}
                rows={3}
              />
            </div>
            <div className="wizard-field-group">
              <IonItem fill="outline" className={createFormErrors.privacyConsentAccepted ? 'ion-invalid ion-touched' : ''}>
                <IonLabel>Acepto la política de privacidad *</IonLabel>
                <IonToggle
                  checked={newLeadData.privacyConsentAccepted}
                  onIonChange={(e: CustomEvent<HTMLIonToggleElement>) => setNewLeadData(p => ({ ...p, privacyConsentAccepted: e.detail.checked }))}
                  slot="end"
                />
              </IonItem>
              {createFormErrors.privacyConsentAccepted && <IonNote color="danger" className="ion-padding-start">{createFormErrors.privacyConsentAccepted}</IonNote>}
            </div>
          </div>
        </IonContent>
      </IonModal>
    </IonPage>
  );
};

export default LeadCapturePage;
